import {mountApplication} from './application-ui.js';
import {mountAIReview,mountAISettings} from './ai-ui.js';
import {scanFiles,sarif,sbom,decision,rules} from './sentinel.mjs';
const icons={shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z M9 12l2 2 4-4',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',folder:'M3 7V5h6l2 2h10v13H3V7Z',scan:'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5 M8 12h8 M12 8v8',alert:'m12 3 10 18H2L12 3Z M12 9v5 M12 17v.1',policy:'M7 3h10v3h4v15H3V6h4 M8 11h8 M8 16h5 M9 3v4h6V3',file:'M5 3h9l5 5v13H5V3Z M14 3v6h5 M8 13h8 M8 17h6',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l3 2',plug:'M8 3v5 M16 3v5 M6 8h12v3a6 6 0 0 1-12 0V8Z M12 17v4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z M9 9a3 3 0 1 1 4 3l-1 1v1 M12 17v.1',search:'M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14Z m5 12 5 5',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4l-2 4Z M10 21h4',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 5v14 M5 12h14',arrow:'M4 12h16 m-5-5 5 5-5 5',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',terminal:'m4 6 6 6-6 6 M13 18h7',copy:'M9 9h12v12H9V9Z M15 9V3H3v12h6',branch:'M6 3v12a3 3 0 1 0 3 3 M6 7a2 2 0 1 0 0-4 2 2 0 1 0 0 4Z M18 7a2 2 0 1 0 0-4 2 2 0 1 0 0 4Z M18 7v2a6 6 0 0 1-6 6H6',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z M12 7v5l3 2',close:'m6 6 12 12 M6 18 18 6',code:'m8 6-6 6 6 6 M16 6l6 6-6 6 m-5-14-2 16',lock:'M5 10h14v11H5V10Z M8 10V7a4 4 0 0 1 8 0v3',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',filter:'M3 5h18 M6 12h12 M9 19h6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7'};
const icon=(name,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const samples=[{name:'payments-api',lang:'TypeScript',branch:'main',files:[{path:'src/api/payments.ts',content:'// Deliberately vulnerable demonstration fixture\nconst api_key = "demo_placeholder_key_123";\nconst query = db.query("SELECT * FROM payments WHERE id = " + req.params.id);\nconst transport = { rejectUnauthorized: false };\nconst config = { debug: true };'},{path:'Dockerfile',content:'FROM node:latest\nUSER root\nCMD ["node", "server.js"]'},{path:'package.json',content:'{"dependencies":{"express":"4.21.2","pg":"8.13.1"}}'}]},
{name:'web-platform',lang:'JavaScript',branch:'main',files:[{path:'src/components/preview.js',content:'// Demonstration fixture\npreview.innerHTML = content;\nconst result = eval(expression);\nconst settings = { debug: true };'},{path:'package.json',content:'{"dependencies":{"react":"19.0.0","vite":"6.0.1"}}'}]},
{name:'auth-service',lang:'Python',branch:'develop',files:[{path:'auth/config.py',content:'"""Demonstration fixture"""\npassword = "demo_not_a_real_password"\nrequests.get(url, verify=False)\nDEBUG = True'},{path:'Dockerfile',content:'FROM python:latest\nUSER root'}]},
{name:'internal-tools',lang:'TypeScript',branch:'main',files:[{path:'src/index.ts',content:'// Safe demonstration fixture\nconst greeting = "Hello, team";\nconsole.log(greeting);'},{path:'package.json',content:'{"dependencies":{"typescript":"5.7.2"}}'}]}];
const initial=()=>({projects:samples.map((s,i)=>({id:'sample-'+i,name:s.name,lang:s.lang,branch:s.branch,demo:true,scan:scanFiles(s.files,s.name),scans:1})),policy:{blockCritical:true,blockHigh:true},audit:[{message:'Demo workspace initialized',detail:'Four sample repositories • deliberately vulnerable fixtures',at:new Date().toISOString()}],baseline:null});
let state;try{state=JSON.parse(localStorage.getItem('sentinel-v1'));if(!state?.projects||!state?.policy||!Array.isArray(state.audit))throw 0;}catch{state=initial();}
let view='Overview',projectId=null,query='',severity='All severities',statusFilter='All statuses',chartMode='By project',lastFocus;
const persist=()=>{try{localStorage.setItem('sentinel-v1',JSON.stringify(state));}catch{toast('Browser storage is full. Export your report before closing.');}};
const log=(message,detail)=>{state.audit.unshift({message,detail,at:new Date().toISOString()});state.audit=state.audit.slice(0,300);persist();};
const allFindings=()=>state.projects.flatMap(p=>p.scan.findings.map(f=>({...f,pid:p.id})));
const openFindings=()=>allFindings().filter(f=>f.status==='Open');
const selected=()=>state.projects.find(p=>p.id===projectId);
const combined=()=>({project:'Sentinel workspace',createdAt:new Date().toISOString(),findings:allFindings(),components:[...new Map(state.projects.flatMap(p=>p.scan.components).map(c=>[c.name+'@'+c.version,c])).values()]});
const badge=(label,cls)=>`<span class="badge ${cls||label.toLowerCase()}">${esc(label)}</span>`;
const ago=at=>{const m=Math.max(0,Math.floor((Date.now()-new Date(at))/60000));return m<1?'Just now':m<60?m+'m ago':m<1440?Math.floor(m/60)+'h ago':Math.floor(m/1440)+'d ago';};
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
function download(filename,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function navigate(next){view=next;projectId=null;query='';severity='All severities';statusFilter='All statuses';render();window.scrollTo(0,0);}
function navButton(name,ic,count){return `<button data-nav="${name}" class="${view===name?'active':''}" title="${name}" ${view===name?'aria-current="page"':''}>${icon(ic,17)}<span>${name}</span>${count?`<b class="count">${count}</b>`:''}</button>`;}
function shell(){return `<aside class="sidebar"><a class="brand" href="#overview" aria-label="Sentinel home"><span class="brandmark">${icon('shield',22)}</span>sentinel<span style="font-size:12px;color:#b2a1db;margin-left:-6px">.</span></a><div class="workspace"><span class="workspace-avatar">A</span><div><strong>Acme workspace</strong><small>Local workspace <span style="color:#bbaad9">↗</span></small></div>${icon('down',12)}</div><div class="label">WORKSPACE</div><nav class="nav">${navButton('Overview','grid')}${navButton('Projects','folder')}${navButton('Application review','branch')}${navButton('Scans','scan')}${navButton('Findings','alert',openFindings().length)}${navButton('Policies','shield')}${navButton('Evidence','file')}${navButton('Audit log','history')}</nav><div class="label nav-gap">MANAGE</div><nav class="nav">${navButton('Integrations','plug')}${navButton('Settings','settings')}</nav><div class="sidebar-bottom"><nav class="nav">${navButton('Documentation','help')}</nav><div class="local-box"><strong><span class="dot"></span>Local-first. Always.</strong><p>Your code stays on your machine.<br>Your security stays in your hands.</p></div><div class="profile"><div class="avatar">JD</div><div><strong>Jamie Davis</strong><small>Personal workspace</small></div><span style="margin-left:auto;color:#9a9eaa">${icon('down',12)}</span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><span>Workspace</span><span>/</span><strong>${esc(view)}</strong>${selected()?`<span>/</span><strong>${esc(selected().name)}</strong>`:''}</div><div class="top-actions"><label class="search">${icon('search',15)}<input aria-label="Search workspace" id="global-search" placeholder="Search anything..." value="${esc(query)}"><span class="key">⌘ K</span></label><span class="divider"></span><button class="icon-button" data-nav="Documentation" aria-label="Documentation">${icon('help',17)}</button><button class="icon-button notification" data-nav="Audit log" aria-label="Activity notifications">${icon('bell',17)}</button><div class="avatar" style="width:27px;height:27px;font-size:9px">JD</div></div></header><div class="content" id="content"></div></main>`;}
function heading(title,subtitle,actions=true){return `<div class="page-heading"><div><div class="eyebrow">YOUR SECURITY WORKSPACE</div><h1>${esc(title)}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions"><button class="btn secondary" data-action="export">${icon('download',13)}Export report</button><button class="btn primary" data-action="new-scan">${icon('plus',14)}New scan</button></div>`:''}</div>`;}
function metrics(){const f=openFindings(),critical=f.filter(x=>x.severity==='Critical').length,pass=state.projects.filter(p=>decision(p.scan,state.policy).decision==='PASS').length;return `<div class="metrics">${metric('Total projects',state.projects.length,'folder','All repositories in this workspace',`${state.projects.filter(p=>p.demo).length} sample`)}${metric('Open findings',f.length,'alert','Across the latest project scans','Needs review',true)}${metric('Critical risks',critical,'shield','Prioritize before your next release',critical?'Action needed':'All clear',!!critical)}${metric('Passing release gates',pass+'/'+state.projects.length,'check','Based on your active policy','Policy enabled')}</div>`;}
function metric(label,value,ic,sub,tag,warn=false){return `<div class="card metric"><div class="metric-top">${label}${icon(ic,15)}</div><div class="metric-value"><strong>${value}</strong><span class="trend ${warn?'warn':''}">${tag}</span></div><small>${sub}</small></div>`;}
const colors={Critical:'#ca777d',High:'#e3ac76',Medium:'#ddc27f',Low:'#a99bcc'};
function chart(){const projects=state.projects.slice(0,6),categories=chartMode==='By severity'?Object.keys(colors):projects.map(p=>p.name),series=chartMode==='By severity'?categories.map(s=>openFindings().filter(f=>f.severity===s).length):projects.map(p=>p.scan.findings.filter(f=>f.status==='Open').length),max=Math.max(8,...series),w=560,h=170,step=(w-60)/Math.max(1,series.length);return `<div class="card"><div class="card-header"><div><h2>Risk overview</h2><p>Open findings from the latest scans</p></div><select id="chart-mode" class="small-select" aria-label="Chart grouping"><option ${chartMode==='By project'?'selected':''}>By project</option><option ${chartMode==='By severity'?'selected':''}>By severity</option></select></div><div class="chart-wrap"><svg role="img" aria-label="Open findings: ${categories.map((c,i)=>c+' '+series[i]).join(', ')}" viewBox="0 0 560 190" preserveAspectRatio="none">${[0,1,2,3,4].map(i=>`<line x1="33" x2="547" y1="${14+i*33}" y2="${14+i*33}" stroke="#eff0f4" stroke-dasharray="3 4"/><text x="20" y="${17+i*33}" fill="#a3a7b3" font-size="8" text-anchor="end">${Math.round(max*(1-i/4))}</text>`).join('')}${series.map((v,i)=>{const x=48+i*step,bh=v/max*126;return `<rect x="${x}" y="${146-bh}" width="${Math.min(45,step*.5)}" height="${bh||2}" rx="4" fill="${chartMode==='By severity'?colors[categories[i]]:'#b5a4da'}"/><text x="${x+Math.min(45,step*.5)/2}" y="${136-bh}" fill="#8a74b8" font-size="9" text-anchor="middle">${v}</text><text x="${x+Math.min(45,step*.5)/2}" y="170" fill="#a0a4af" font-size="8" text-anchor="middle">${esc(categories[i].length>15?categories[i].slice(0,13)+'…':categories[i])}</text>`;}).join('')}</svg></div><div class="chart-legend"><span><i class="legend-dot" style="background:#b5a4da"></i>Open findings</span><span>Latest scan per project</span></div></div>`;}
function distribution(){const f=openFindings(),total=f.length;let start=0;const gradient=Object.entries(colors).map(([s,c])=>{const end=start+(total?f.filter(x=>x.severity===s).length/total*100:0);const seg=`${c} ${start}% ${end}%`;start=end;return seg;}).join(',');return `<div class="card"><div class="card-header"><div><h2>Findings by severity</h2><p>Know what needs your attention</p></div>${icon('filter',14)}</div><div class="risk-body"><div class="donut" style="background:${total?`conic-gradient(${gradient})`:'#eeeaf5'}"><div class="donut-label"><strong>${total}</strong><span>open findings</span></div></div><div class="risk-legend">${Object.entries(colors).map(([s,c])=>`<div><i class="legend-dot" style="background:${c}"></i>${s}<b>${f.filter(x=>x.severity===s).length}</b></div>`).join('')}</div></div><div class="risk-footer">${icon('help',12)}Severity is rule-based. Validate findings before acting.</div></div>`;}
function projectTable(limit){const ps=state.projects.filter(p=>p.name.toLowerCase().includes(query.toLowerCase())).slice(0,limit||1000);return `<div class="card"><div class="table-scroll"><table><thead><tr><th>Project</th><th>Branch</th><th>Open findings</th><th>Release gate</th><th>Last scan</th><th></th></tr></thead><tbody>${ps.map(p=>{const f=p.scan.findings.filter(x=>x.status==='Open'),d=decision(p.scan,state.policy);return `<tr data-project="${p.id}" tabindex="0" role="button" aria-label="Open ${esc(p.name)}"><td><div class="project-cell"><span class="repo-icon">${icon('code',16)}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.lang)} <span style="padding:0 3px">·</span> ${p.demo?'Sample repository':'Local source'}</small></div></div></td><td><span class="branch">${icon('branch',11)}${esc(p.branch)}</span></td><td><div class="severity-counts">${Object.keys(colors).map(s=>`<span class="badge ${s.toLowerCase()}" title="${s}">${f.filter(x=>x.severity===s).length} ${s[0]}</span>`).join('')}</div></td><td>${d.decision==='BLOCK'?`<span class="badge blocked">${icon('alert',10)}Blocked</span>`:`<span class="badge pass">${icon('check',10)}Passing</span>`}</td><td class="muted">${ago(p.scan.createdAt)}</td><td class="muted">${icon('chevron',12)}</td></tr>`;}).join('')}</tbody></table>${!ps.length?'<div class="empty">No projects found. Start a new scan to add one.</div>':''}</div><div class="table-footer"><span>Showing ${ps.length} of ${state.projects.length} projects</span><button class="text-btn" data-nav="Projects">View all projects ${icon('arrow',11)}</button></div></div>`;}
function activity(){const rows=state.audit.slice(0,3);return `<div class="card"><div class="card-header"><h2>Recent activity</h2><button class="text-btn" data-nav="Audit log">View audit log ${icon('arrow',11)}</button></div><div class="activity">${rows.map(a=>`<div class="activity-row"><span class="activity-check">${icon('check',12)}</span><div><strong>${esc(a.message)}</strong><p>${esc(a.detail)}</p></div><time>${ago(a.at)}</time></div>`).join('')}${rows.length===1?`<div class="activity-row"><span class="activity-check" style="background:#f1edf8;color:#a28cc7">${icon('shield',12)}</span><div><strong>Release policy is active</strong><p>Critical and high findings block the release gate</p></div></div><div class="activity-row"><span class="activity-check">${icon('lock',12)}</span><div><strong>Your workspace stays local</strong><p>Source files are processed only on this device</p></div></div>`:''}</div></div>`;}
function cliCard(){return `<div class="cli-card"><div class="cli-label">${icon('terminal',13)} BUILT FOR YOUR TERMINAL</div><h2>One command. A safer release.</h2><p>Scan any local project. Take the evidence with you.<br>No account required. Local source processing.</p><div class="command"><span><em>$</em>node sentinel.mjs scan .</span><button data-action="copy-cli" aria-label="Copy CLI command">${icon('copy',13)}</button></div><a href="sentinel.mjs" download>Download the CLI ${icon('arrow',11)}</a></div>`;}
function overview(){return heading('Overview','Security, before you ship. Here’s where your projects stand.')+`<div class="banner"><div class="banner-icon">${icon('shield',22)}</div><div><strong>Your next release starts with confidence.</strong><p>Find risks early. Fix what matters. Ship with the evidence to back it up.</p></div><button data-nav="Policies">View release policy ${icon('arrow',13)}</button></div>`+metrics()+`<div class="grid-charts">${chart()}${distribution()}</div><section class="projects-section"><div class="section-heading"><div class="sub"><h2>Your projects</h2><span class="bubble">${state.projects.length}</span></div><div class="table-tools"><button class="small-select" data-action="new-scan">${icon('plus',11)} Add project</button></div></div>${projectTable(4)}</section><div class="bottom-grid">${activity()}${cliCard()}</div>`;}
function findings(){let rows=selected()?selected().scan.findings.map(f=>({...f,pid:projectId})):allFindings();rows=rows.filter(f=>(severity==='All severities'||f.severity===severity)&&(statusFilter==='All statuses'||f.status===statusFilter)&&[f.title,f.path,f.project].join(' ').toLowerCase().includes(query.toLowerCase()));return `${selected()?`<div class="card project-summary"><div class="repo-icon">${icon('code',20)}</div><div><h2>${esc(selected().name)}</h2><p>${selected().scan.files} files · ${selected().scan.lines} lines · ${selected().demo?'Sample repository':'Local source'} · ${selected().scan.components.length} dependencies inventoried</p></div><button style="margin-left:auto" class="btn" data-action="rescan">${icon('scan',13)}Rescan</button></div>`:''}<div class="section-heading"><div class="sub"><h2>${rows.length} findings</h2></div><div class="table-tools"><select class="small-select" id="severity-filter" aria-label="Filter severity">${['All severities',...Object.keys(colors)].map(s=>`<option ${severity===s?'selected':''}>${s}</option>`).join('')}</select><select class="small-select" id="status-filter" aria-label="Filter status">${['All statuses','Open','Accepted risk','False positive','Resolved'].map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="card table-scroll"><table><thead><tr><th>Finding</th><th>Severity</th><th>Project / location</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(f=>`<tr data-finding="${esc(f.id)}" data-pid="${f.pid}" tabindex="0" role="button"><td><strong style="font-weight:550">${esc(f.title)}</strong><small style="display:block;font-size:9px;margin-top:5px">${f.ruleId} · ${f.cwe}</small></td><td>${badge(f.severity)}</td><td>${esc(f.project)}<small style="display:block;font-size:9px;margin-top:5px">${esc(f.path)}:${f.line}</small></td><td>${badge(f.status,f.status==='Open'?'neutral':'pass')}</td><td>${icon('chevron',12)}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No findings match these filters.</div>':''}</div>`;}
function evidence(){return heading('Release evidence','Portable, reviewable evidence from your latest local scans.',false)+`<div class="note" style="margin-bottom:20px">Exports include sample projects until you remove them in Settings. Source-project dependency inventory is not a CVE scan. Application review has its own Python advisory lookup and complete report export. OpenVEX is unavailable because these rules do not establish product vulnerability status.</div><div class="report-grid">${[['SARIF','file','Static analysis results for security tooling and code review.','sarif'],['SBOM','code','CycloneDX 1.5 inventory from uploaded package manifests and lockfiles.','sbom'],['Policy decision','shield','A snapshot of the release gate, active rules, and blocker count.','policy'],['Findings report','alert','All findings, locations, explanations, and recorded triage decisions.','json'],['Audit log','history','A local activity history of scans, policy changes, and triage.','audit'],['Baseline','scan','Save the current findings to compare against your next scan.','baseline']].map(([title,ic,desc,type])=>`<div class="card report-card"><span style="color:#8e75c4">${icon(ic,24)}</span><h3>${title}</h3><p>${desc}</p><button class="btn" data-export="${type}">${icon(type==='baseline'?'plus':'download',13)}${type==='baseline'?'Save baseline':'Export '+title}</button></div>`).join('')}</div>${state.baseline?`<div class="note" style="margin-top:18px">Baseline saved ${new Date(state.baseline.at).toLocaleString()}. ${allFindings().filter(f=>!state.baseline.ids.includes(f.pid+':'+f.id)).length} new findings since baseline.</div>`:''}`;}
function policies(){return heading('Release policies','Turn security findings into a clear release decision.',false)+`<div class="card"><div class="card-header"><h2>Default release policy</h2>${badge('Active','pass')}</div>${[['blockCritical','Block critical findings','Prevent a passing release gate while critical findings remain open.'],['blockHigh','Block high findings','Require high-severity findings to be resolved or explicitly triaged.']].map(([k,t,d])=>`<label class="policy-row"><div><strong>${t}</strong><p>${d}</p></div><input type="checkbox" class="switch" data-policy="${k}" ${state.policy[k]?'checked':''} aria-label="${t}"></label>`).join('')}<div class="policy-row"><div><strong>Policy scope</strong><p>Latest scan per project. Only open findings block the release gate.</p></div><button class="btn" data-export="policy">${icon('download',13)}Export decision</button></div></div><div class="note" style="margin-top:18px">A passing gate means no configured blockers were found by the supported rules. It does not establish that an application is secure. Accepted risks and false positives remain in the findings report.</div>`;}
function scans(){return heading('Scans','Latest scan results, with a traceable history in your audit log.')+`<div class="card table-scroll"><table><thead><tr><th>Project</th><th>Completed</th><th>Files scanned</th><th>Findings</th><th>Gate</th><th></th></tr></thead><tbody>${state.projects.map(p=>`<tr data-project="${p.id}" tabindex="0" role="button"><td>${esc(p.name)} ${p.demo?badge('Sample','neutral'):''}</td><td class="muted">${new Date(p.scan.createdAt).toLocaleString()}</td><td>${p.scan.files}</td><td>${p.scan.findings.length}</td><td>${badge(decision(p.scan,state.policy).decision,decision(p.scan,state.policy).decision==='PASS'?'pass':'blocked')}</td><td>${icon('chevron',12)}</td></tr>`).join('')}</tbody></table>${!state.projects.length?'<div class="empty">No scans yet. Start your first scan.</div>':''}</div>`;}
function audit(){return heading('Audit log','A local record of the actions behind your release decisions.',false)+`<div class="section-heading"><span class="muted" style="font-size:11px">${state.audit.length} events stored on this device</span><button class="btn" data-export="audit">${icon('download',13)}Export log</button></div><div class="card table-scroll"><table><thead><tr><th>Event</th><th>Details</th><th>Time</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${esc(a.message)}</td><td class="muted">${esc(a.detail)}</td><td class="muted">${new Date(a.at).toLocaleString()}</td></tr>`).join('')}</tbody></table></div><p class="note" style="margin-top:18px">This browser-local log stores the latest 300 events. It is editable by the device owner and is not a tamper-proof compliance record.</p>`;}
function integrations(){return heading('Developer workflow','Use portable outputs to connect your security workflow.',false)+`<div class="report-grid"><div class="card report-card">${icon('terminal',25)}<h3>Local CLI</h3><p>Run the same checks in any local project with Node.js 20 or later.</p><a href="sentinel.mjs" download class="btn">${icon('download',13)}Download CLI</a></div><div class="card report-card">${icon('branch',25)}<h3>GitHub Actions</h3><p>Download a CI template that scans your repository and uploads SARIF.</p><button class="btn" data-action="ci">${icon('download',13)}Download template</button></div><div class="card report-card">${icon('file',25)}<h3>Security tooling</h3><p>Export SARIF 2.1.0 and CycloneDX 1.5 for compatible tools.</p><button class="btn" data-nav="Evidence">View evidence ${icon('arrow',13)}</button></div></div><div class="note" style="margin-top:20px">Direct SaaS connections, hosted CI ingestion, and runtime capture are not connected in this version.</div>`;}
function settings(){return heading('Workspace settings','Control your local data and demonstration projects.',false)+`<div id="ai-settings"></div><div class="card"><div class="policy-row"><div><strong>Browser-local storage</strong><p>Findings and triage are saved in this browser. Raw files are not persisted. Bounded, redacted source excerpts and AI reviews are saved with findings.</p></div>${badge('Enabled','pass')}</div><div class="policy-row"><div><strong>Remove sample projects</strong><p>Keep your uploaded projects and remove the seeded demonstration repositories.</p></div><button class="btn" data-action="remove-samples">Remove samples</button></div><div class="policy-row"><div><strong>Restore demo projects</strong><p>Add any missing sample repositories without replacing your projects.</p></div><button class="btn" data-action="restore-samples">Restore samples</button></div><div class="policy-row"><div><strong>Backup workspace</strong><p>Export findings, triage, policy, audit history, and baseline as JSON.</p></div><button class="btn" data-export="backup">Export backup</button></div></div>`;}
function docs(){return heading('Documentation','A small, honest security workflow that works on your machine.',false)+`<div class="card help-content"><h3>1. Scan your source</h3><p>Select New scan, then upload supported source files or paste a file. JavaScript, TypeScript, Python, JSON, Dockerfiles, environment files, YAML, shell and text files are supported. Keep individual files below 1 MB and the selection below 20 MB. Rules run in your browser. Optional AI review sends a bounded, redacted excerpt to the local server and Ollama on this PC.</p><h3>2. Review and triage</h3><p>Open a finding to review its matched location, rule explanation, and remediation guidance. Check the real data flow before deciding. Record an accepted risk, false positive, or resolved status with a review note. A rescan resets the status of a still-present finding to Open.</p><h3>3. Evaluate the release gate</h3><p>Critical and high findings block by default. Adjust Policies to match your team's requirements, then export the decision from Evidence. Save a baseline to see newly introduced findings.</p><h3>Use the CLI</h3><pre class="code">node sentinel.mjs scan .
node sentinel.mjs scan . --format sarif > results.sarif
node sentinel.mjs scan . --format sbom > sbom.json</pre><p>Download <a href="sentinel.mjs" download style="color:var(--purple)">sentinel.mjs</a> first. The CLI skips symlinks, dependencies, and build folders. Exit code 0: passing gate; 1: policy blocked; 2: scan error.</p><h3>What this version detects</h3><p>${rules.map(r=>r.title).join(' · ')}.</p><h3>Scope and limitations</h3><p>These are line-based heuristics, with possible false positives and false negatives. Application review adds optional OSV lookup for Python environments, declared dependency graphs, OpenAPI checks, authentication patterns, and Docker/Compose configuration checks. It does not perform runtime reachability analysis, live URL scanning, built-image vulnerability scanning, Docker attack execution, SaaS connections, or OpenVEX analysis. Source scanning does not run AI automatically. Rule explanations are labeled. Open a finding to request an actual local-model review with Ollama; the result includes source citations and uncertainty. A passing scan is not a security guarantee.</p></div>`;}
function render(){document.querySelector('#app').innerHTML=shell();let html;if(view==='Application review')html='<div id="application-root"></div>';else if(view==='Overview')html=overview();else if(view==='Projects')html=heading(selected()?.name||'Projects',selected()?'Review the latest findings and release evidence.':'Every repository. One security workspace.')+(selected()?findings():projectTable());else if(view==='Findings')html=heading('Findings','Prioritize the risks that matter, then track every decision.')+findings();else if(view==='Scans')html=scans();else if(view==='Policies')html=policies();else if(view==='Evidence')html=evidence();else if(view==='Audit log')html=audit();else if(view==='Integrations')html=integrations();else if(view==='Settings')html=settings();else html=docs();document.querySelector('#content').innerHTML=html+`<footer class="page-footer"><span>${icon('shield',11)}Sentinel · Security, before you ship.</span><span><i class="dot" style="width:4px;height:4px"></i>Source processing local <span style="padding:0 6px">·</span> v0.3.0 ${state.projects.some(p=>p.demo)?'· Sample data included':''}</span></footer>`;if(view==='Settings')mountAISettings(document.querySelector('#ai-settings'));if(view==='Application review')mountApplication(document.querySelector('#application-root'),{state,persist,log});}
function modal(title,sub,body,large=false){lastFocus=document.activeElement;document.querySelector('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${sub}</p></div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close',18)}</button></header><div class="modal-body">${body}</div></section></div>`;setTimeout(()=>document.querySelector('.modal input,.modal select,.modal button')?.focus(),20);}
function close(){document.querySelector('#overlay').innerHTML='';lastFocus?.focus();}
let scanTarget=null;
function newScan(rescan=false){scanTarget=rescan?selected()?.id:null;const target=state.projects.find(p=>p.id===scanTarget);modal(rescan?'Run a new scan':'Start a new scan','Local source. Real checks. Your code stays on this device.',`<form id="scan-form"><label class="field">Project name<input id="project-name" required maxlength="70" value="${esc(target?.name||'')}" placeholder="e.g. checkout-service"></label><div class="tabs"><button type="button" class="active" data-scan-tab="upload">Upload files</button><button type="button" data-scan-tab="paste">Paste source</button><button type="button" data-scan-tab="sample">Try a sample</button></div><div id="scan-input"><label class="upload">${icon('folder',28)}<strong>Select source files</strong><small>JS, TS, Python, JSON, Dockerfile, YAML & more<br>Up to 1 MB per file · 20 MB total</small><input id="source-files" type="file" multiple aria-label="Select source files"></label></div><p class="note">Eight heuristic rules check source and configuration. Package manifests create an inventory; use Application review for optional Python dependency advisory lookup.</p><div id="scan-error" class="error" role="alert"></div><div class="modal-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" id="scan-submit">${icon('scan',14)}Run scan</button></div></form>`);document.querySelector('#scan-form').dataset.mode='upload';}
function findingDetail(pid,id){const p=state.projects.find(x=>x.id===pid),f=p.scan.findings.find(x=>x.id===id);modal(esc(f.title),`${esc(p.name)} · ${esc(f.path)}:${f.line}`,`${badge(f.severity)} <span class="muted" style="font-size:10px;margin-left:8px">${f.ruleId} · ${f.cwe} · Heuristic match</span><div class="detail-block"><h3>Matched source</h3><pre class="code">${f.line}  ${esc(f.excerpt)}</pre></div><div class="detail-block"><h3>Why it matters</h3><p>${esc(f.why)}</p></div><div class="detail-block"><h3>Suggested remediation</h3><p>${esc(f.fix)}</p></div><p class="note">The guidance above is rule-based. Generate a separate contextual AI review below.</p><div id="finding-ai"></div><form id="triage-form" data-pid="${pid}" data-id="${esc(id)}"><label class="field" style="margin-top:20px">Triage status<select id="triage-status">${['Open','Accepted risk','False positive','Resolved'].map(s=>`<option ${s===f.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Review note<textarea id="triage-note" style="min-height:75px" maxlength="2000" placeholder="Explain your decision for the next reviewer...">${esc(f.note||'')}</textarea></label><div id="triage-error" class="error" role="alert"></div><div class="modal-actions"><button type="button" class="btn" data-action="close">Close</button><button class="btn primary" type="submit">Save triage</button></div></form>`,true);mountAIReview(document.querySelector('#finding-ai'),{finding:f,scanCreatedAt:p.scan.createdAt,onSave:()=>{if(!state.projects.some(project=>project.scan.findings.includes(f)))throw new Error("The project was rescanned or removed. Open the current finding and analyze again.");persist();},onAudit:log});}
function exportData(type){const scan=selected()?.scan||combined(),name=(selected()?.name||'sentinel-workspace').replace(/[^a-z0-9_-]/gi,'-');if(type==='baseline'){state.baseline={at:new Date().toISOString(),ids:allFindings().map(f=>f.pid+':'+f.id)};log('Baseline saved',state.baseline.ids.length+' findings captured');render();toast('Baseline saved on this device');return;}const data=type==='sarif'?sarif(scan):type==='sbom'?sbom(scan):type==='policy'?decision(scan,state.policy):type==='audit'?state.audit:type==='backup'?state:{...scan,policy:decision(scan,state.policy),scope:'Heuristic source analysis. Sample projects labeled in project metadata.',projects:state.projects.map(p=>({name:p.name,sample:p.demo}))};download(name+'-'+type+(type==='sarif'?'.sarif':'.json'),data);log('Evidence exported',type.toUpperCase()+' · '+scan.project);toast(type.toUpperCase()+' downloaded');}
function exportModal(){modal('Export release evidence','Take a reviewable snapshot of your current workspace.',`<label class="field">Report format<select id="export-format"><option value="json">JSON · Findings and policy</option><option value="sarif">SARIF · Static analysis results</option><option value="sbom">CycloneDX · Dependency inventory</option><option value="policy">JSON · Policy decision</option></select></label><p class="note">Includes ${selected()?esc(selected().name):state.projects.length+' projects'}. ${state.projects.some(p=>p.demo)?'Sample projects are included in workspace exports.':''} Exports may include code excerpts; review before sharing.</p><div class="modal-actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="confirm-export">${icon('download',13)}Download report</button></div>`);}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}if(e.target.closest('.brand')){e.preventDefault();navigate('Overview');return;}const project=e.target.closest('[data-project]');if(project){view='Projects';projectId=project.dataset.project;render();return;}const finding=e.target.closest('[data-finding]');if(finding){findingDetail(finding.dataset.pid,finding.dataset.finding);return;}const exp=e.target.closest('[data-export]');if(exp){exportData(exp.dataset.export);return;}const tab=e.target.closest('[data-scan-tab]');if(tab){const mode=tab.dataset.scanTab;document.querySelector('#scan-form').dataset.mode=mode;document.querySelectorAll('[data-scan-tab]').forEach(b=>b.classList.toggle('active',b===tab));document.querySelector('#scan-input').innerHTML=mode==='upload'?`<label class="upload">${icon('folder',28)}<strong>Select source files</strong><small>Supported source files · 1 MB per file · 20 MB total</small><input id="source-files" type="file" multiple aria-label="Select source files"></label>`:mode==='paste'?`<label class="field">File name<input id="source-path" value="src/app.js" maxlength="250" required></label><label class="field">Source code<textarea id="source-code" placeholder="Paste source code to scan…" required></textarea></label>`:`<label class="field">Demonstration repository<select id="sample-select">${samples.map((s,i)=>`<option value="${i}">${s.name} · ${s.lang}</option>`).join('')}</select></label><p class="note" style="margin-bottom:16px">These fixtures deliberately include unsafe patterns. The same real detection rules run on samples and uploaded files.</p>`;if(mode==='sample'&&!document.querySelector('#project-name').value)document.querySelector('#project-name').value='demo-payments-api';return;}
const action=e.target.closest('[data-action]')?.dataset.action;if(action==='close')close();if(action==='new-scan')newScan();if(action==='rescan')newScan(true);if(action==='export')exportModal();if(action==='confirm-export'){exportData(document.querySelector('#export-format').value);close();}if(action==='copy-cli'){try{await navigator.clipboard.writeText('node sentinel.mjs scan .');toast('Command copied. Download the CLI to get started.');}catch{toast('Command: node sentinel.mjs scan .');}}if(action==='remove-samples'){state.projects=state.projects.filter(p=>!p.demo);log('Sample projects removed','Uploaded projects preserved');render();toast('Sample projects removed');}if(action==='restore-samples'){const add=initial().projects.filter(p=>!state.projects.some(x=>x.id===p.id));state.projects.push(...add);log('Demo projects restored',add.length+' projects added');render();toast(add.length+' sample projects added');}if(action==='ci'){download('sentinel-security.yml',`name: Sentinel security\non: [push, pull_request]\npermissions:\n  contents: read\n  security-events: write\njobs:\n  scan:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: '22'\n      # Commit the downloaded sentinel.mjs to .sentinel/sentinel.mjs first.\n      - name: Scan repository\n        run: node .sentinel/sentinel.mjs scan . --format sarif > results.sarif\n      - uses: github/codeql-action/upload-sarif@v3\n        if: always()\n        with:\n          sarif_file: results.sarif\n`,'text/yaml');toast('CI template downloaded; see the setup comment inside.');}});
document.addEventListener('change',e=>{if(e.target.id==='chart-mode'){chartMode=e.target.value;render();}if(e.target.id==='severity-filter'){severity=e.target.value;render();}if(e.target.id==='status-filter'){statusFilter=e.target.value;render();}if(e.target.dataset.policy){state.policy[e.target.dataset.policy]=e.target.checked;log('Release policy updated',e.target.dataset.policy+': '+e.target.checked);toast('Release policy saved');}if(e.target.id==='sample-select')document.querySelector('#project-name').value='demo-'+samples[e.target.value].name;});
document.addEventListener('input',e=>{if(e.target.id==='global-search'){query=e.target.value;view='Findings';projectId=null;const pos=e.target.selectionStart;render();const input=document.querySelector('#global-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('submit',async e=>{if(e.target.id==='triage-form'){e.preventDefault();const form=e.target,p=state.projects.find(p=>p.id===form.dataset.pid),f=p.scan.findings.find(f=>f.id===form.dataset.id),s=document.querySelector('#triage-status').value,n=document.querySelector('#triage-note').value.trim();if(s!=='Open'&&!n){document.querySelector('#triage-error').textContent='Add a review note to explain this triage decision.';return;}f.status=s;f.note=n;f.reviewedAt=new Date().toISOString();log('Finding triaged',p.name+' · '+f.ruleId+' → '+s);close();render();toast('Triage decision saved');return;}if(e.target.id!=='scan-form')return;e.preventDefault();const form=e.target,button=document.querySelector('#scan-submit'),error=document.querySelector('#scan-error');error.textContent='';button.disabled=true;button.textContent='Scanning locally…';try{const mode=form.dataset.mode,name=document.querySelector('#project-name').value.trim();if(!name)throw new Error('Enter a project name.');let files=[],demo=false,lang='Mixed';if(mode==='sample'){const sample=samples[document.querySelector('#sample-select').value];files=sample.files;demo=true;lang=sample.lang;}else if(mode==='paste'){const content=document.querySelector('#source-code').value,path=document.querySelector('#source-path').value.trim();if(!content.trim()||!path)throw new Error('Enter a file name and source code.');if(new Blob([content]).size>1000000)throw new Error('Source exceeds the 1 MB file limit.');files=[{path,content}];}else{const list=[...document.querySelector('#source-files').files];if(!list.length)throw new Error('Select at least one source file.');if(list.some(f=>f.size>1000000)||list.reduce((n,f)=>n+f.size,0)>20000000)throw new Error('Files exceed the 1 MB per-file or 20 MB total limit.');const supported=list.filter(f=>/\.(js|jsx|ts|tsx|py|json|yml|yaml|env|txt|sh)$/i.test(f.name)||/^(Dockerfile|\.env)/.test(f.name));if(supported.length!==list.length)throw new Error('Unsupported file type. Select source files, manifests, or Dockerfiles; archives and binaries are not supported.');files=await Promise.all(supported.map(async f=>({path:f.webkitRelativePath||f.name,content:await f.text()})));}await new Promise(r=>setTimeout(r,250));const result=scanFiles(files,name);let p=state.projects.find(p=>p.id===scanTarget);if(p){p.name=name;p.scan=result;p.demo=demo;p.scans++;}else{p={id:crypto.randomUUID(),name,lang,branch:'local',demo,scan:result,scans:1};state.projects.unshift(p);}log('Scan completed',name+' · '+files.length+' files · '+result.findings.length+' findings');close();view='Projects';projectId=p.id;query='';render();toast('Scan complete · '+result.findings.length+' findings detected');}catch(err){error.textContent=err.message;button.disabled=false;button.innerHTML=icon('scan',14)+'Run scan';}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.querySelector('#global-search')?.focus();}if(e.key==='Escape')close();if(e.key==='Enter'&&e.target.matches('tr[data-project],tr[data-finding]'))e.target.click();if(e.key==='Tab'&&document.querySelector('.modal')){const items=[...document.querySelectorAll('.modal button,.modal input,.modal textarea,.modal select,.modal a')].filter(x=>!x.disabled&&x.offsetParent!==null);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
persist();render();
